// @req: REQ-010
const assert = require('assert');
const unalib = require('../../libs/unalib');

describe('REQ-010 (Unit) — Validación de mensajes vacíos en unalib', function () {
  it('debe rechazar mensajes con contenido vacío', function () {
    const res = unalib.validateMessage({ mensaje: '', nombre: 'Usuario', color: '#000000' });
    assert.strictEqual(res === false || res === null || (res && res.valid === false) || (res && !res.mensaje), true, 'Mensaje vacío debe ser invalidado');
  });
  it('debe rechazar mensajes con solo espacios en blanco', function () {
    const res = unalib.validateMessage({ mensaje: '     ', nombre: 'Usuario', color: '#000000' });
    assert.strictEqual(res === false || res === null || (res && res.valid === false) || (res && !res.mensaje?.trim()), true, 'Mensaje con solo espacios debe ser invalidado');
  });
});

