// @req: REQ-010
const assert = require('assert');
const ioClient = require('socket.io-client');

describe('REQ-010 (Integration) — Rechazo de mensajes vacíos en Socket.IO', function () {
  this.timeout(5000);
  let socket;
  const port = process.env.PORT || 3000;

  before(function (done) {
    socket = ioClient.connect(`http://localhost:${port}`, { forceNew: true });
    socket.on('connect', done);
  });

  after(function () {
    if (socket && socket.connected) socket.disconnect();
  });

  it('el servidor no debe retransmitir mensajes con contenido vacío o espacios', function (done) {
    let received = false;
    socket.on('Evento-Mensaje-Server', (data) => {
      if (data && (!data.mensaje || data.mensaje.trim() === '')) {
        received = true;
      }
    });
    socket.emit('Evento-Mensaje-Server', JSON.stringify({ mensaje: '   ', nombre: 'TestUser', color: '#111111' }));
    setTimeout(() => {
      assert.strictEqual(received, false, 'El servidor no debió retransmitir mensaje vacío');
      done();
    }, 600);
  });
});

