// @req: REQ-010
const { test, expect } = require('@playwright/test');

test.describe('REQ-010 (E2E) — Validación de mensajes vacíos en navegador', () => {
  test('al enviar mensaje vacío no debe agregar transcript y debe notificar al usuario', async ({ page }) => {
    await page.goto('/');
    let dialogTriggered = false;
    page.on('dialog', async dialog => {
      dialogTriggered = true;
      await dialog.dismiss();
    });
    const initialMessages = await page.locator('#m').count();
    await page.locator('#m').fill('   ');
    await page.locator('button[type="submit"]').click();
    const finalMessages = await page.locator('#m').count();
    expect(finalMessages).toBe(initialMessages);
  });
});
